cd ~/.claude/projects && node -e '
const fs=require("fs"),path=require("path");
const re=/sk-or-[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9_-])?/g;
const walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):[path.join(d,e.name)]);
const files=fs.readdirSync(".").filter(n=>n.startsWith("-home-walter-Github-chiri-ai-editor")).flatMap(walk);
const stats={};
for(const f of files){const t=fs.readFileSync(f).toString("latin1");for(const m of t.matchAll(re)){const prev=t[m.index-1]||"";const L=m[0].length;const k=(/[A-Za-z0-9]/.test(prev)?"wordprefix:":"")+(L<30?m[0]:"LEN"+L+(/^sk-or-***MASKED***[0-9a-f]{64}$/.test(m[0])?"-REALSHAPE":""));stats[k]=(stats[k]||0)+1}}
console.log(stats);
const bin=files.filter(f=>!f.endsWith(".jsonl")&&!f.endsWith(".json")&&!f.endsWith(".txt")&&!f.endsWith(".md"));console.log("other ext:",bin.length, [...new Set(bin.map(f=>path.extname(f)))]);
'

